<?php require_once __DIR__.'/inc/config.php'; require_once __DIR__.'/inc/auth.php'; require_admin(); $orders=read_orders(); $o=$orders[(int)($_GET['i']??-1)]??null; admin_header('Order Details'); ?><section class="admin-panel"><h2>Order details</h2><?php if(!$o):?><p>Order not found.</p><?php else:?><p><strong>Order ID:</strong> <?=e($o['orderId']??'')?></p><p><strong>Status:</strong> <?=e($o['status']??'Pending')?></p><p><strong>Customer:</strong> <?=e($o['customer']??'')?> | <strong>Table:</strong> <?=e($o['tableNumber']??'')?></p><h3>Items</h3><?php foreach(($o['items']??[]) as $item):?><p><?=e($item['name'])?> x <?=e($item['qty']??1)?> - Rs <?=number_format((float)($item['price']??0),2)?></p><?php endforeach;?><h3>Total: Rs <?=number_format((float)($o['price']??0),2)?></h3><?php endif;?><a class="btn" href="admin.php">Back</a></section><?php admin_footer();?>
